"""Declare only new identity native image jobs; never calls an API."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
R='referencias/kit/'
STYLE="Use the attached reference images as the strict visual base: same art style, same character design,\nsame colors and same rendering quality. Style: polished stylized 3D children's animation (Pixar-like),\nsunny outdoor adventure mood, rounded shapes, soft daylight, vivid saturated colors. Brand palette:\npink #E3205D, blue #3E93D0, yellow #F6BB33, green #A0C630, navy #1E2A4A, white. Real-world play only:\nno video game controller, no headset, no screens, no game coins, no pixels, no outer space. No text,\nno letters, no logos, no watermark. Clean edges, fully inside the frame with margin."
CHAR={'ruivo': ('01_heroi-explorador.png', 'Red-haired boy with orange spiky hair, large brown eyes, white lab coat, blue T-shirt, beige cargo shorts, binoculars hanging from neck, olive green backpack, blue and white sneakers. No headset, controller or handheld map.'), 'loira': ('03_fase2-construtora-loira.png', 'Blonde girl with wavy hair, yellow construction helmet with goggles on brim and pink bow, white lab coat, pink blouse, tool belt, denim skirt, pink sneakers. No handheld block tower.'), 'cacheado': ('02_fase1-explorador-cacheado.png', 'Black boy with curly hair, beige safari hat, explorer vest with pockets, white T-shirt, beige shorts, brown backpack, blue sneakers. Magnifying glass and compass attached to BELT.'), 'sapo': ('05_fase4-gincana-leao-e-sapo.png', 'ONLY green #A0C630 and white robot FROG on RIGHT, black visor with smiling blue LED eyes, green and white headband, whistle hanging from neck. No ball, no lion.')}
POSES={'idle': (2, '1 standing relaxed and smiling with eyes open; 2 same standing position with chest subtly raised for breathing, eyes CLOSED in a blink. Both in right-facing 3/4 view.'), 'corrida': (4, '1 running contact RIGHT leg extended forward and left behind; 2 passing position right foot underneath hips and left knee lifting; 3 contact LEFT leg extended forward and right behind; 4 passing left foot underneath hips and right knee lifting. Arms counter-swing. All in TRUE SIDE PROFILE facing and moving SCREEN RIGHT; only one eye visible, nose, chest and feet point right. Camera strictly sees the side, much more sideways than idle.'), 'ar': (2, '1 upward jump, arms lifted and knees bent; 2 falling, arms spread, surprised expression. Both in clear TRUE SIDE PROFILE facing SCREEN RIGHT, only one eye visible, nose and feet point right, camera strictly sees the side.'), 'extras': (4, '1 pushing an INVISIBLE object to SCREEN RIGHT with both empty palms extended, leaning right, TRUE SIDE PROFILE, only one eye visible; 2 comic defeat, dizzy spiral eyes, crouched but upright, no injury; 3 celebrating with one fist raised; 4 waving hello towards camera in front/3/4 view. No physical objects. Keep standing-equivalent scale and head size identical even for bent poses.')}
WORLDS={'exploradores': (['06_fundos/fundo_aventura_9x16.png', '04_fases/fase_1_exploradores-em-acao.png', '02_key-visual/keyvisual_principal_9x16.png'], 'Sunny trail between green hills, river and waterfall, wooden signs and unlettered maps, discreet giant compass.'), 'construtores': (['04_fases/fase_2_desafio-dos-construtores.png', '06_fundos/fundo_aventura_9x16.png'], 'Distant colorful building brick city, toy brick crane, bunting.'), 'robotica': (['04_fases/fase_3_mestres-da-robotica.png', '05_elementos/icones/icone_05_engrenagem.png'], 'Bright airy robotics workshop, gears, small educational robots on shelves, no screens.'), 'gincana': (['04_fases/fase_4_gincana-das-aventuras.png', '05_elementos/icones/icone_08_cone-gincana.png'], 'Sunny grassy outdoor games field, cones, hoops, bunting and balls.'), 'conquistas': (['04_fases/fase_5_grandes-conquistas.png', '05_elementos/icones/icone_10_trofeu.png'], 'Outdoor celebration stage, sparse confetti, trophies, medals, friendly giant brick robot strongly blurred in far background.'), 'lobby': (['06_fundos/fundo_claro_4x5.png'], 'Cream clean map background with dotted trail, blocks and leaves only in corners.')}
requests={}
def job(key,refs,body,transparent=False):
    prompt=STYLE+'\n'+('Isolated on genuine transparent background, no floor or cast shadow.\n' if transparent else '')+body
    path=ROOT/'tools/prompts'/f'{key}.txt'
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(prompt)
    requests[key]=dict(key=key,out=f'assets/_bruto/{key}.png',size='1536x1024',refs=refs,prompt_file=str(path.relative_to(ROOT)),prompt=prompt,transparent=transparent)
for char,(ref,description) in CHAR.items():
    for kind,(n,poses) in POSES.items():
        job(f'{char}_{kind}',[R+'personagens/'+ref],f'Exactly {n} full-body poses of the SAME character in ONE horizontal row, evenly spaced, generous transparent gaps and margins. Identical head size, body scale and invisible baseline. Left to right: {poses} Character: {description} Match reference face, hair silhouette, huge child head and compact body, proportions, materials and outfit exactly. All hands EMPTY; equipment attached to body. No extra props, no characters from other references. Keep entire body and hair inside each pose with margin. No invented text; leave chest badge blank; do not apply a logo to sprites. No rim glow. Use case: stylized-concept. Asset: platform game animation strip.',True)
for world,(refs,scene) in WORLDS.items():
    refs=[R+r for r in refs]
    job(world+'_longe',refs,f'Wide horizontal 20:9 backdrop, composed to fit 2400x1080. {scene} No characters except the distant blurred friendly brick robot for conquistas only. No playable platforms or foreground floor. Calm spacious slightly defocused center; details at edges. No lettering, badge outlines, borders or logos. Use references for visual style and objects only, not poster composition.')
    if world!='lobby':
        job(world+'_meio',refs,f'Wide horizontal 20:9 TRANSPARENT parallax middle layer. Theme: {scene} Sparse silhouettes ONLY in bottom third and far left/right edges. Entire top and central two thirds fully transparent. No sky, floor, characters, robots, text or maps with symbols. No ground shadow. Clean simple shapes, no halo.',True)
(ROOT/'tools/requests.json').write_text(json.dumps(requests,ensure_ascii=False,indent=2))
print(f'{len(requests)} new identity jobs declared.')
